const escapeHTML = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let theme = 'light';
try { theme = localStorage.getItem('milo-theme') === 'dark' ? 'dark' : 'light'; } catch (_) {}
function applyTheme(){document.documentElement.dataset.theme=theme;document.querySelectorAll('[data-theme-toggle]').forEach(b=>{b.textContent=theme==='dark'?'☀ Light mode':'◐ Dark mode';b.setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'dark'} mode`)});document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#101827':'#f5f7fb')}
const themeButton = () => `<button class="theme-toggle" data-theme-toggle>${theme==='dark'?'☀ Light mode':'◐ Dark mode'}</button>`;

