prepPlans.northstar.topics[0].url=prepPlans.orbit.topics[1].url;
let prepRole='orbit';
const completedTopics=new Set();
function preparation(){const plan=prepPlans[prepRole];return head('Prepare with purpose.','Topics, courses, and practice linked to the roles you have applied for.')+`<div class="prep-layout"><aside class="prep-index"><span class="eyebrow">YOUR APPLIED ROLES</span>${Object.entries(prepPlans).map(([key,p])=>`<button class="role-choice ${prepRole===key?'selected':''}" data-prep-role="${key}" aria-pressed="${prepRole===key}"><strong>${p.company}</strong><span>${p.role}</span><small>${p.status}</small></button>`).join('')}<div class="notice">Recommendations are illustrative. Real plans will use job descriptions, your confirmed skills, and interview dates. Missing CV evidence does not establish a skill gap.</div></aside><section><div class="prep-title"><div><span class="eyebrow">PREPARATION PLAN</span><h2>${plan.role}</h2><p class="muted">${plan.company} · ${plan.status}</p></div><span class="badge">${plan.topics.filter((_,i)=>completedTopics.has(prepRole+':'+i)).length}/${plan.topics.length} studied</span></div><div class="time-note">Short on time? Start with the priority topic and practise one answer. Course completion alone does not establish interview readiness.</div>${plan.topics.map((t,i)=>`<article class="learning-card"><div class="learning-top"><span class="topic-number">0${i+1}</span><div><div class="eyebrow">${t.priority.toUpperCase()} / ${t.type.toUpperCase()}</div><h2>${t.title}</h2></div><span class="badge">${t.time}</span></div><p class="why">${t.why}</p><div class="learning-columns"><div><h3>Recommended resource</h3><a href="${t.url}" target="_blank" rel="noopener noreferrer">${t.resource} ↗</a><p class="muted">${t.description}</p><small>Provider link checked 8 Oct 2026. Practice time is our estimate.</small></div><div class="practice"><h3>Practise answering</h3><p>${t.question}</p><details><summary>Suggested exercise</summary><p>${t.exercise}</p></details></div></div><div class="learning-bottom"><small>Learning progress stays in this preview session.</small><button data-study="${i}" aria-pressed="${completedTopics.has(prepRole+':'+i)}">${completedTopics.has(prepRole+':'+i)?'✓ Studied · Undo':'Mark as studied'}</button></div></article>`).join('')}</section></div>`}
function connections(){return head('Your inboxes, connected.','Choose where application history comes from.')+`<div class="grid">${[['Gmail','Application confirmations and job alerts'],['Live / Outlook','Recruiter conversations and interview invitations']].map(([name,sub])=>`<section class="panel"><div class="panel-head"><h2>${name}</h2>${pill('Not connected','amber')}</div><p class="muted">${sub}</p><div class="notice">Read-only access. You choose the import period and review uncertain matches.</div><div style="margin-top:20px"><button class="primary" data-demo="This is a design preview. OAuth connection will be added during implementation.">Connect ${name}</button></div></section>`).join('')}</div><section class="panel wide"><h2>Import preferences</h2><div class="row"><label for="period">History to import</label><select id="period"><option>Last 6 months</option><option>Last 12 months</option><option>Last 24 months</option></select></div><div class="row"><span>Uncertain email matches</span>${pill('Review before accepting')}</div><div class="row"><span>AI processing</span><span class="muted">Provider not configured</span></div></section>`}
function members(){return head('A workspace by invitation.','Manage access to your self-hosted instance.',button('Invite a member','Invitations','primary'))+`<section class="panel"><div class="panel-head"><h2>Members & invitations</h2>${pill('Public registration disabled')}</div><div class="row"><div class="row-main"><span class="avatar">AM</span><div><h3>Alex Morgan</h3><small>alex@example.com</small></div></div><button data-user="alex">Manage user</button>${pill('Administrator','purple')}</div><div class="row"><div class="row-main"><span class="avatar">JT</span><div><h3>Jordan Taylor</h3><small>jordan@example.com</small></div></div><button data-user="jordan">Manage user</button>${pill('Member')}</div><div class="row"><div><h3>sam@example.com</h3><small>Invitation expires in 3 days</small></div>${pill('Pending','amber')}</div><div class="notice">Members have separate private application records, mailboxes, and documents. Account management does not grant access to their job-search content.</div></section>`}
function documents(){return head('The version you actually sent.','Keep CVs and cover letters linked to their applications.')+`<section class="panel">${[['Alex_Morgan_CV_v3.pdf','Current CV · Used for Orbit Systems and Harbour Digital'],['Orbit_cover_letter_v1.pdf','Cover letter · Orbit Systems · 6 October'],['Alex_Morgan_CV_v2.pdf','Previous CV · Used for Koru Technologies']].map(([n,s])=>`<div class="row"><div><h3>${n}</h3><p>${s}</p></div>${button('Assess CV','CV studio')}</div>`).join('')}</section>`}
let managedUser='alex';
function account(){return head('Your account. Your preferences.','Manage your profile, appearance, and job-search preferences.')+`<div class="account-layout"><aside class="profile-summary panel"><span class="avatar large-avatar">${escapeHTML(profile.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><h2>${escapeHTML(profile.name)}</h2><p class="muted">${escapeHTML(profile.email)}</p>${pill(profile.role,'purple')}<div class="profile-divider"></div><small>Private job-search workspace</small><p class="muted">Your applications and documents belong to your account.</p>${button('Mailbox connections','Connections')}${button('Sign out preview','Login')}</aside><div class="stack"><section class="panel"><div class="section-label">01 / PROFILE</div><h2>Personal details</h2><form id="profile-form" class="form settings-form"><div class="field-pair"><label>Full name<input id="profile-name" required maxlength="80" value="${escapeHTML(profile.name)}" autocomplete="name"></label><label>Location<input id="profile-location" required maxlength="100" value="${escapeHTML(profile.location)}" autocomplete="address-level2"></label></div><label>Email address<input type="email" value="${escapeHTML(profile.email)}" readonly><small>Email changes will require verification in the live app.</small></label><div><button class="primary" type="submit">Save profile preview</button></div><small>Changes last for this preview session only.</small></form></section><section class="panel"><div class="section-label">02 / PREFERENCES</div><h2>Make this space yours</h2><div class="row"><div><h3>Appearance</h3><p>Choose a light or dark workspace.</p></div>${themeButton()}</div><div class="row"><div><h3>Target roles</h3><p>Project Manager · Delivery Lead · Programme Manager</p></div><span class="badge">SAMPLE PREFERENCES</span></div><div class="row"><div><h3>Learning time</h3><p>30 minutes a day · Focus on upcoming interviews</p></div></div></section><section class="panel"><div class="section-label">03 / SECURITY</div><h2>Account security</h2><div class="row"><div><h3>Password & two-factor authentication</h3><p>Security controls will be available with server authentication.</p></div><span class="badge">NOT CONNECTED</span></div><div class="row"><div><h3>Your data</h3><p>Export and deletion controls will be available for your private records.</p></div></div></section></div></div>`}
function userManagement(){const u=managedUser==='jordan'?{name:'Jordan Taylor',email:'jordan@example.com',role:'Member',initial:'JT'}:{...profile,initial:'AM'};return head('Manage member','Administrator workspace · Individual account',button('Back to members','Members'))+`<div class="account-layout"><aside class="panel profile-summary"><span class="avatar large-avatar">${u.initial}</span><h2>${escapeHTML(u.name)}</h2><p class="muted">${escapeHTML(u.email)}</p>${pill(u.role,'purple')}<div class="profile-divider"></div><small>Joined 1 October 2026 · Sample account</small></aside><div class="stack"><section class="panel"><h2>Access & permissions</h2><div class="row"><div><h3>Account status</h3><p>Can sign in to this instance.</p></div>${pill('Active')}</div><div class="row"><div><h3>Instance role</h3><p>Controls account administration permissions.</p></div><span class="badge">${u.role}</span></div><div class="notice">This is an account-management preview. Member applications, documents, and email content are private.</div></section><section class="panel"><h2>Account actions</h2><div class="row"><div><h3>Password reset</h3><p>Let the member securely reset their password.</p></div><button data-demo="Preview only. No reset email was sent.">Preview reset</button></div><div class="row"><div><h3>Access review</h3><p>Role changes and account suspension will require server-side authorization.</p></div><span class="badge">NOT CONNECTED</span></div></section></div></div>`}
function login(){return `<div class="login-shell"><header class="auth-header"><a class="brand" href="#Login"><span class="mark">↗</span>Milo</a>${themeButton()}</header><main class="login-layout"><section class="login-story"><span class="eyebrow">A LITTLE CLARITY. A LOT OF MOMENTUM.</span><h1>Your next role<br>starts with<br><span>your next move.</span></h1><p>Keep your applications together. Find your strongest fit. Walk into interviews prepared.</p><div class="orbit-art" aria-hidden="true"><div class="orbit-circle circle-one"></div><div class="orbit-circle circle-two"></div><span class="orbit-arrow">↗</span><span class="orbit-label label-one">TRACK</span><span class="orbit-label label-two">PREPARE</span><span class="orbit-label label-three">PROGRESS</span></div></section><section class="login-card"><span class="badge">INVITE-ONLY WORKSPACE</span><h2>Welcome back.</h2><p class="muted">Sign in to your private career workspace.</p><form id="login-form" class="form"><label>Email address<input type="email" autocomplete="username" placeholder="you@example.com" required></label><label>Password<span class="password-field"><input id="login-password" type="password" autocomplete="current-password" placeholder="Enter your password" required><button type="button" data-show-password aria-label="Show password" aria-pressed="false">Show</button></span></label><button class="primary" type="submit">Sign in →</button></form><button class="text-button" data-demo="Password recovery will be available once authentication is implemented.">Forgot password?</button><div class="login-note">New here? Your administrator can send you an invitation.</div><div class="preview-link">Design preview · No credentials are sent or stored.<br><div class="preview-personas"><button data-persona="Member">Preview member workspace</button><button data-persona="Administrator">Preview administrator workspace</button></div></div></section></main></div>`}
function invitations(){return head('Invite someone to Milo.','Administrator workspace · Manage invitations to this instance.',button('Back to members','Members'))+`<div class="grid"><section class="panel"><h2>Create an invitation</h2><form id="invitation-form" class="form settings-form"><label>Email address<input type="email" autocomplete="off" required placeholder="colleague@example.com"></label><label>Account role<select><option>Member</option></select><small>Invited members cannot manage users or invitations.</small></label><div class="row"><span>Invitation expires after</span><span class="badge">7 days</span></div><button class="primary" type="submit">Preview invitation</button><small>Draft only. No invitation is created or sent.</small></form></section><section class="panel"><h2>Pending invitation</h2><div class="row"><div><h3>sam@example.com</h3><small>Member · Expires in 3 days</small></div>${pill('Pending','amber')}</div><div class="row"><span>Recipient’s invitation screen</span>${button('Preview acceptance','Invite')}</div><div class="notice">Only administrators create, view, resend, or revoke invitations. Recipients can accept their own invitation through its private link.</div></section></div>`}
function denied(){return head('Administrator access required.','Your account does not have permission to manage members or invitations.',button('Return to my workspace','Today','primary'))+`<section class="panel"><h2>Your personal workspace is available</h2><p class="muted" style="margin-top:12px">You can manage your own profile, applications, documents, and mailbox connections.</p></section>`}
function invite(){return `<div class="auth-theme">${themeButton()} ${button('Sign in','Login')}</div><main class="auth"><div><div class="brand"><span class="mark">↗</span>Milo</div><span class="eyebrow">Your private job-search workspace</span><h1>Your next chapter.<br><span style="color:var(--cyan)">All in one place.</span></h1><p class="muted">Remember where you applied. Understand which roles fit. Keep your next action in sight.</p><div class="notice">You’ve been invited to a self-hosted Milo instance. Your job-search records stay separate from other members.</div></div><section class="panel"><h2>Accept your invitation</h2><p class="muted" style="margin:8px 0 24px">Create your account for sam@example.com</p><form id="invite-form" class="form"><label>Your name<input autocomplete="name" required placeholder="Sam Taylor"></label><label>Password<input type="password" autocomplete="new-password" minlength="12" required placeholder="At least 12 characters"></label><button class="primary" type="submit">Create account</button></form><small style="display:block;margin:18px 0">Preview only. No account or password will be saved.</small>${button('Back to sign in','Login')}</section></main>`}
/* FEATURE_MODULE */
const views={'Today':today,'Applications':applications,'Email inbox':inbox,'Opportunities':opportunities,'CV studio':cv,'Connections':connections,'Members':members,'Invitations':invitations,'Interview prep':preparation,'Detail':detail,'Documents':documents,'My account':account,'User management':userManagement,'Login':login,...toolkitViews};
function render(route){current=Object.prototype.hasOwnProperty.call(views,route)||route==='Invite'?route:'Today';app.innerHTML=adminRoutes.has(current)&&!isAdmin()?shell(denied()):current==='Invite'?invite():current==='Login'?login():shell(views[current]());bindToolkit();bindCareer();document.title=`Milo · ${current}`;applyTheme();window.scrollTo(0,0);if(current==='Applications'){const update=()=>{applicationFilters.query=document.querySelector('#filter').value;applicationFilters.status=document.querySelector('#status').value;applicationFilters.mailbox=document.querySelector('#mailbox-filter').value;applicationFilters.sort=document.querySelector('#application-sort').value;document.querySelector('#application-results').innerHTML=applicationResults();document.querySelector('#result-count').textContent=`${filteredApplications().length} sample records`};document.querySelector('#filter').addEventListener('input',update);['#status','#mailbox-filter','#application-sort'].forEach(id=>document.querySelector(id).addEventListener('change',update))}document.querySelector('#email-import-form')?.addEventListener('submit',e=>{e.preventDefault();const provider=document.querySelector('#import-provider').value,job=document.querySelector('#import-job').value,from=document.querySelector('#import-from').value.trim(),subject=document.querySelector('#import-subject').value.trim(),body=document.querySelector('#import-body').value.trim();if(!jobs.some(j=>j.id===job)||!['Gmail','Outlook'].includes(provider)||!from||!subject||!body){notify('Complete all email fields.');return}emails.unshift({...mail('imported-'+(++importedEmailCount),job,provider,'Date unknown',from,subject,body,'Uncertain','Needs review'),to:profile.email,imported:true});inboxFilter='Needs review';render('Email inbox');notify('Email text added for review in this session.');});document.querySelector('#application-edit')?.addEventListener('submit',e=>{e.preventDefault();const j=getJob();const previous=j.status;j.status=document.querySelector('#edit-stage').value;j.followUp=document.querySelector('#edit-followup').value;j.next=document.querySelector('#edit-next').value.trim();j.notes=document.querySelector('#edit-notes').value;j.manualStatus=true;j.history.unshift({label:'Record updated by you',note:previous===j.status?'Notes and next action updated.':`${previous} → ${j.status}`});render('Detail');notify('Application updated for this preview session.');});document.querySelector('#invitation-form')?.addEventListener('submit',e=>{e.preventDefault();if(!isAdmin()){render('Invitations');return}notify('Invitation preview only. Nothing was created or sent.');});document.querySelector('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#profile-name').value.trim();const place=document.querySelector('#profile-location').value.trim();if(!name||!place){notify('Enter a name and location.');return}profile.name=name;profile.location=place;render('My account');notify('Profile updated for this preview session.');});document.querySelector('#login-form')?.addEventListener('submit',e=>{e.preventDefault();e.target.reset();notify('Login preview only. Use Explore the workspace to review the design.');});document.querySelector('#invite-form')?.addEventListener('submit',e=>{e.preventDefault();notify('Invitation preview complete. No account was created.');render('Today')});document.querySelector('#global-search')?.addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value;location.hash='Applications';setTimeout(()=>{const f=document.querySelector('#filter');if(f){f.value=q;f.dispatchEvent(new Event('input'))}},0)}})}
let toastTimer;function notify(message){const toast=document.querySelector('#toast');toast.textContent=message;toast.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.style.display='none',5000)}
document.addEventListener('click',e=>{handleToolkit(e);handleCareer(e);const view=e.target.closest('[data-app-view]');if(view){applicationView=view.dataset.appView;render('Applications')}const filter=e.target.closest('[data-inbox-filter]');if(filter){inboxFilter=filter.dataset.inboxFilter;render('Email inbox')}const approve=e.target.closest('[data-email-approve]');if(approve){const email=emails.find(x=>x.id===approve.dataset.emailApprove);const target=document.querySelector(`[data-link-choice="${email.id}"]`).value;if(jobs.some(j=>j.id===target)){email.job=target;email.review='Linked';jobs.find(j=>j.id===target).history.unshift({label:'Email association confirmed',note:email.subject});render(current);notify('Email linked. The application stage is unchanged.')}}const ignore=e.target.closest('[data-email-ignore]');if(ignore){emails.find(x=>x.id===ignore.dataset.emailIgnore).review='Ignored';render(current);notify('Message ignored. Your application record is unchanged.')}const persona=e.target.closest('[data-persona]');if(persona){const admin=persona.dataset.persona==='Administrator';profile.role=admin?'Administrator':'Member';profile.name=admin?'Alex Morgan':'Jordan Taylor';profile.email=admin?'alex@example.com':'jordan@example.com';location.hash='Today';render('Today')}const toggle=e.target.closest('[data-theme-toggle]');if(toggle){theme=theme==='light'?'dark':'light';try{localStorage.setItem('milo-theme',theme)}catch(_){}applyTheme()}const show=e.target.closest('[data-show-password]');if(show){const input=document.querySelector('#login-password');const visible=input.type==='password';input.type=visible?'text':'password';show.textContent=visible?'Hide':'Show';show.setAttribute('aria-label',visible?'Hide password':'Show password');show.setAttribute('aria-pressed',String(visible))}const user=e.target.closest('[data-user]');if(user&&!isAdmin()){render('User management');return}if(user){managedUser=user.dataset.user;location.hash='User management';render('User management')}const role=e.target.closest('[data-prep-role]');if(role){prepRole=role.dataset.prepRole;render('Interview prep')}const study=e.target.closest('[data-study]');if(study){const key=prepRole+':'+study.dataset.study;completedTopics.has(key)?completedTopics.delete(key):completedTopics.add(key);render('Interview prep')}const route=e.target.closest('[data-route]');if(route){e.preventDefault();if(route.dataset.job&&jobs.some(j=>j.id===route.dataset.job))selectedJob=route.dataset.job;if(route.dataset.prep)prepRole=route.dataset.prep;const hash=route.dataset.route+(route.dataset.job?'?job='+route.dataset.job:'');if(decodeURIComponent(location.hash.slice(1))===hash)render(route.dataset.route);else location.hash=hash}const demo=e.target.closest('[data-demo]');if(demo)notify(demo.dataset.demo)});
function routeFromHash(){try{const [route,query]=decodeURIComponent(location.hash.slice(1)).split('?');const id=new URLSearchParams(query||'').get('job');if(jobs.some(j=>j.id===id))selectedJob=id;return route||'Today'}catch(_){return 'Today'}}
window.addEventListener('hashchange',()=>render(routeFromHash()));render(routeFromHash());
